import{_ as t,o as a,c as i,an as e}from"./chunks/framework.Ba0314i4.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started/installation.md","filePath":"getting_started/installation.md","lastUpdated":null}'),n={name:"getting_started/installation.md"};function l(p,s,h,r,o,d){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h1><p>This page covers getting AtmosTransport.jl onto a machine and verifying the install with the synthetic-fixture test suite. No external met data is required to complete this page.</p><h2 id="Prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#Prerequisites" aria-label="Permalink to &quot;Prerequisites {#Prerequisites}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Requirement</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Julia</strong></td><td style="text-align:right;">1.10 or newer; tested on 1.10 and 1.12. <a href="https://github.com/JuliaLang/juliaup" target="_blank" rel="noreferrer">juliaup</a> is the recommended installer.</td></tr><tr><td style="text-align:right;"><strong>Git</strong></td><td style="text-align:right;">Standard.</td></tr><tr><td style="text-align:right;"><strong>Disk</strong></td><td style="text-align:right;">~2 GB for source + dependencies + precompiled artifacts. Real meteorological datasets are separate (tens to hundreds of GB).</td></tr><tr><td style="text-align:right;"><strong>GPU backend</strong> <em>(optional)</em></td><td style="text-align:right;">NVIDIA CUDA or Apple Silicon Metal can enable GPU acceleration. The CPU backend works without any GPU drivers.</td></tr></tbody></table><p>Metal runs require <code>Float32</code> numerics. The runtime rejects Metal with <code>float_type = &quot;Float64&quot;</code> before model construction.</p><h2 id="Get-the-code" tabindex="-1">Get the code <a class="header-anchor" href="#Get-the-code" aria-label="Permalink to &quot;Get the code {#Get-the-code}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RemoteSensingTools/AtmosTransport.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AtmosTransport</span></span></code></pre></div><h2 id="Install-Julia-dependencies" tabindex="-1">Install Julia dependencies <a class="header-anchor" href="#Install-Julia-dependencies" aria-label="Permalink to &quot;Install Julia dependencies {#Install-Julia-dependencies}&quot;">​</a></h2><p>The repository pins its dependencies via <code>Project.toml</code> and <code>Manifest.toml</code>. Instantiate them once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p>Dependencies include <code>KernelAbstractions</code>, <code>NCDatasets</code>, <code>FFTW</code>, <code>StaticArrays</code>, and (as weak deps) <code>CUDA</code> and <code>Metal</code>. Plan on a ~5–10 minute first-time precompile.</p><h2 id="Verify-the-install" tabindex="-1">Verify the install <a class="header-anchor" href="#Verify-the-install" aria-label="Permalink to &quot;Verify the install {#Verify-the-install}&quot;">​</a></h2><p>The core test suite runs end-to-end on <strong>synthetic fixtures</strong> — no external met data needed. It exercises the preprocessor, the runtime, and the diagnostic tools across all three grid topologies.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span></span></code></pre></div><p>Expected output (abbreviated):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test Summary:                | Pass  Total  Time</span></span>
<span class="line"><span>Met source trait             |   18     18  0.2s</span></span>
<span class="line"><span>IdentityRegrid passthrough   |   15     15  3.7s</span></span>
<span class="line"><span>GEOS reader                  |   48     48  8.3s</span></span>
<span class="line"><span>GEOS → CS passthrough        | 3467   3467 11.4s</span></span>
<span class="line"><span>GEOS convection wiring       |   26     26 12.8s</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>If <code>Pkg.test()</code> finishes green, the install is sound and you can proceed to <a href="/AtmosTransport.jl/previews/PR5/getting_started/first_run#First-run">First run</a>.</p><h2 id="Optional:-GPU-stack" tabindex="-1">Optional: GPU stack <a class="header-anchor" href="#Optional:-GPU-stack" aria-label="Permalink to &quot;Optional: GPU stack {#Optional:-GPU-stack}&quot;">​</a></h2><p>If you have a GPU and want runtime acceleration, use the backend selector in your run TOML:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">architecture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">use_gpu = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or &quot;cuda&quot; / &quot;metal&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numerics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Float32&quot;</span></span></code></pre></div><p>The driver script (<code>scripts/run_transport.jl</code>) preloads CUDA or Metal before AtmosTransport when needed.</p><p>To verify the GPU is visible to Julia:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using CUDA; CUDA.versioninfo()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Metal; Metal.versioninfo()&#39;</span></span></code></pre></div><p>CUDA can run either <code>Float32</code> or <code>Float64</code> depending on the hardware and validation goal:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># in your run config TOML</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">architecture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">use_gpu    = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend    = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cuda&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numerics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Float32&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or &quot;Float64&quot; on CUDA / CPU</span></span></code></pre></div><p>Note that the L40S and most consumer / data-center GPUs lack first-class F64 throughput; F32 is the recommended default for production runs.</p><h2 id="Optional:-multi-threaded-I/O" tabindex="-1">Optional: multi-threaded I/O <a class="header-anchor" href="#Optional:-multi-threaded-I/O" aria-label="Permalink to &quot;Optional: multi-threaded I/O {#Optional:-multi-threaded-I/O}&quot;">​</a></h2><p>For double-buffered I/O overlap (disk reads in parallel with GPU compute), start Julia with multiple threads:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --threads=2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run_transport.jl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">config.tom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The runtime detects available threads automatically.</p><h2 id="What&#39;s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#What&#39;s-next" aria-label="Permalink to &quot;What&amp;#39;s next {#What&#39;s-next}&quot;">​</a></h2><ul><li><p><a href="/AtmosTransport.jl/previews/PR5/getting_started/first_run#First-run">First run</a> — invoke the runtime on an existing config.</p></li><li><p><a href="/AtmosTransport.jl/previews/PR5/getting_started/inspecting_output#Inspecting-output">Inspecting output</a> — verify a transport binary or snapshot NetCDF.</p></li></ul>`,32)])])}const g=t(n,[["render",l]]);export{k as __pageData,g as default};
